import pandas as pd

def solve(data):
     s = pd.Series(data['values'], dtype='Float64')
     value = s.mean()
     return {'known': s.dropna().astype(float).tolist(), 'missing': int(s.isna().sum()), 'mean': None if pd.isna(value) else float(value)}
